--region public
function CardProgressionEquipmentListCell:RefreshUI(goodsNodeData, isShowLock, index)
    self.index         = index
    self.goodsNodeData = goodsNodeData
    KTool.SetActive(self.GoodNode.gameObject, true)

    self.reScaleComp:ResetScale()

    ---@type GoodNodeMB
    local mbEnv = CfUtils.GetLuaScr(self.GoodNode.gameObject, GoodNodePrefabPath)
    if mbEnv then
        mbEnv:Reload(goodsNodeData)
        if isShowLock ~= nil then
            mbEnv:RefreshLockedShowState(isShowLock)
        end
    end
    
    local id = checkInt(goodsNodeData.id)
    if id == 0 then return end

    ---@type EquipmentComponent
    local equipComp        = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
    local dojo  = equipComp:GetEquipById(id)
    if checkInt(dojo.bindPlayerCardId) == 0 then
        CfUtils.SetActive(self.CultivateOverseaEquipEngraveHead, false)
        return
    end

    CfUtils.SetActive(self.CultivateOverseaEquipEngraveHead, true)
    local CardProgressionConstants = import("Game.CardProgression.CardProgressionConstants")
    local scr = CfUtils.GetLuaScr(self.CultivateOverseaEquipEngraveHead, CardProgressionConstants.EnvPath.EquipmentEngraveNode)
    if not scr then return end

    scr:RefreshNode(dojo)
end

